-- Generated explicit read policies; no client table writes.
alter table public.schools enable row level security;
create policy read_scope on public.schools for select to authenticated using (id=private.school() and private.role() is not null or private.role()='owner');
alter table public.subscriptions enable row level security;
create policy read_scope on public.subscriptions for select to authenticated using (school_id=private.school() and private.role() in ('administrator','teacher') or private.role()='owner');
alter table public.memberships enable row level security;
create policy read_scope on public.memberships for select to authenticated using (private.role() is not null and (id=auth.uid() or school_id=private.school() and private.role()='administrator' or role='student' and private.student_access(id)));
alter table public.classes enable row level security;
create policy read_scope on public.classes for select to authenticated using (school_id=private.school() and private.role() is not null);
alter table public.teacher_assignments enable row level security;
create policy read_scope on public.teacher_assignments for select to authenticated using (school_id=private.school() and private.role() is not null);
alter table public.student_registry enable row level security;
create policy read_scope on public.student_registry for select to authenticated using (school_id=private.school() and private.role() is not null and (student_id=auth.uid() or private.student_access(student_id)));
alter table public.enrollments enable row level security;
create policy read_scope on public.enrollments for select to authenticated using (school_id=private.school() and private.role() is not null and (student_id=auth.uid() or private.assigned(class_id)));
alter table public.audit_events enable row level security;
create policy read_scope on public.audit_events for select to authenticated using (school_id=private.school() and (private.role()='administrator' or actor_id=auth.uid() or subject_id=auth.uid() and action like 'account.%'));
alter table public.import_jobs enable row level security;
create policy read_scope on public.import_jobs for select to authenticated using (school_id=private.school() and (actor_id=auth.uid() or private.role()='administrator'));
alter table public.import_rows enable row level security;
create policy read_scope on public.import_rows for select to authenticated using (exists(select 1 from public.import_jobs j where j.id=job_id));
alter table public.outbox enable row level security;
create policy read_scope on public.outbox for select to authenticated using (false);
alter table public.notifications enable row level security;
create policy read_scope on public.notifications for select to authenticated using (recipient_id=auth.uid() and school_id=private.school() and private.role() is not null);
alter table public.question_drafts enable row level security;
create policy read_scope on public.question_drafts for select to authenticated using (author_id=auth.uid() and school_id=private.school() and private.role()='teacher');
alter table public.exam_versions enable row level security;
create policy read_scope on public.exam_versions for select to authenticated using (private.can_exam(id) or school_id=private.school() and private.role()='administrator');
alter table public.exam_questions enable row level security;
create policy read_scope on public.exam_questions for select to authenticated using (private.can_exam(version_id));
alter table public.exam_recipients enable row level security;
create policy read_scope on public.exam_recipients for select to authenticated using (school_id=private.school() and (student_id=auth.uid() and private.role()='student' or private.exam_teacher(version_id)));
alter table public.attempts enable row level security;
create policy read_scope on public.attempts for select to authenticated using (school_id=private.school() and (student_id=auth.uid() and private.role()='student' or private.exam_teacher(version_id)));
alter table public.answers enable row level security;
create policy read_scope on public.answers for select to authenticated using (exists(select 1 from public.attempts a where a.id=attempt_id and (a.student_id=auth.uid() or private.exam_teacher(a.version_id))));
alter table public.results enable row level security;
create policy read_scope on public.results for select to authenticated using (school_id=private.school() and private.report_result(version_id,student_id));
alter table public.integrity_events enable row level security;
create policy read_scope on public.integrity_events for select to authenticated using (exists(select 1 from public.attempts a where a.id=attempt_id and (a.student_id=auth.uid() and private.role()='student' or private.exam_teacher(a.version_id))));
alter table public.integrity_reviews enable row level security;
create policy read_scope on public.integrity_reviews for select to authenticated using (exists(select 1 from public.attempts a where a.id=attempt_id and (a.student_id=auth.uid() and private.role()='student' or private.exam_teacher(a.version_id) or private.role()='administrator' and a.school_id=private.school())));
alter table public.groups enable row level security;
create policy read_scope on public.groups for select to authenticated using (private.can_group(id) or school_id=private.school() and private.role()='administrator');
alter table public.group_memberships enable row level security;
create policy read_scope on public.group_memberships for select to authenticated using (school_id=private.school() and not private.active_attempt() and (student_id=auth.uid() and private.role()='student' or private.group_teacher(group_id)));
alter table public.posts enable row level security;
create policy read_scope on public.posts for select to authenticated using (not deleted and private.can_group(group_id));
alter table public.post_reads enable row level security;
create policy read_scope on public.post_reads for select to authenticated using (student_id=auth.uid() and private.role()='student' and exists(select 1 from public.posts where id=post_id));
alter table public.query_policies enable row level security;
create policy read_scope on public.query_policies for select to authenticated using (school_id=private.school() and private.role() is not null and not private.active_attempt());
alter table public.queries enable row level security;
create policy read_scope on public.queries for select to authenticated using (private.can_query(id) or school_id=private.school() and private.role()='administrator');
alter table public.query_cycles enable row level security;
create policy read_scope on public.query_cycles for select to authenticated using (exists(select 1 from public.queries q where q.id=query_id));
alter table public.query_messages enable row level security;
create policy read_scope on public.query_messages for select to authenticated using (private.can_query(query_id));
alter table public.deadline_revisions enable row level security;
create policy read_scope on public.deadline_revisions for select to authenticated using (exists(select 1 from public.queries q where q.id=query_id));
alter table public.attachments enable row level security;
create policy read_scope on public.attachments for select to authenticated using (state='clean' and ((post_id is not null and exists(select 1 from public.posts p where p.id=post_id)) or (query_message_id is not null and exists(select 1 from public.query_messages m where m.id=query_message_id))));
alter table public.student_insights enable row level security;
create policy read_scope on public.student_insights for select to authenticated using (school_id=private.school() and not private.active_attempt() and (student_id=auth.uid() and private.role()='student' or private.role()='administrator'));
alter table public.teacher_feedback enable row level security;
create policy read_scope on public.teacher_feedback for select to authenticated using (school_id=private.school() and not private.active_attempt() and (student_id=auth.uid() or private.assigned(class_id,subject)));
alter table public.report_exports enable row level security;
create policy read_scope on public.report_exports for select to authenticated using (school_id=private.school() and actor_id=auth.uid() and private.role() in ('teacher','administrator') and expires_at>now());
alter table public.teacher_profiles enable row level security;
create policy read_scope on public.teacher_profiles for select to authenticated using (private.profile_visible(id) or school_id=private.school() and (teacher_id=auth.uid() and private.role()='teacher' or private.role()='administrator'));
alter table public.profile_revisions enable row level security;
create policy read_scope on public.profile_revisions for select to authenticated using (school_id=private.school() and (author_id=auth.uid() and private.role()='teacher' or private.role()='administrator'));
alter table public.professional_updates enable row level security;
create policy read_scope on public.professional_updates for select to authenticated using (approved and private.profile_visible(profile_id));
alter table public.teacher_articles enable row level security;
create policy read_scope on public.teacher_articles for select to authenticated using (published_revision is not null and not archived and private.profile_visible(profile_id) and (school_id=private.school() or audience='public' and exists(select 1 from public.schools where id=school_id and public_enabled)) or school_id=private.school() and (author_id=auth.uid() and private.role()='teacher' or private.role()='administrator'));
alter table public.article_revisions enable row level security;
create policy read_scope on public.article_revisions for select to authenticated using (exists(select 1 from public.teacher_articles a where a.id=article_id and (a.published_revision=article_revisions.id or a.school_id=private.school() and (a.author_id=auth.uid() and private.role()='teacher' or private.role()='administrator'))));
alter table public.content_publications enable row level security;
create policy read_scope on public.content_publications for select to authenticated using (false);
alter table public.public_assets enable row level security;
create policy read_scope on public.public_assets for select to authenticated using (false);
grant usage on schema private to authenticated;
revoke all on all tables in schema public from anon, authenticated;
grant select on public.schools,public.subscriptions,public.memberships,public.classes,public.teacher_assignments,public.student_registry,public.enrollments,public.audit_events,public.import_jobs,public.import_rows,public.outbox,public.notifications,public.question_drafts,public.exam_versions,public.exam_questions,public.exam_recipients,public.attempts,public.answers,public.results,public.integrity_events,public.integrity_reviews,public.groups,public.group_memberships,public.posts,public.post_reads,public.query_policies,public.queries,public.query_cycles,public.query_messages,public.deadline_revisions,public.attachments,public.student_insights,public.teacher_feedback,public.report_exports,public.teacher_profiles,public.profile_revisions,public.professional_updates,public.teacher_articles,public.article_revisions,public.content_publications,public.public_assets to authenticated;
revoke execute on all functions in schema private from public, anon, authenticated;
grant execute on function private.me(),private.school(),private.role(),private.staff(uuid),private.assigned(uuid,text),private.student_access(uuid),private.active_attempt(),private.exam_teacher(uuid),private.can_exam(uuid),private.group_teacher(uuid),private.can_group(uuid),private.can_query(uuid),private.profile_visible(uuid),private.report_result(uuid,uuid) to authenticated;
revoke execute on all functions in schema public from public, anon, authenticated;
grant execute on function public.create_class(jsonb),public.assign_teacher(jsonb),public.publish_exam(jsonb),public.start_attempt(jsonb),public.save_answer(jsonb),public.submit_attempt(jsonb),public.review_grade(jsonb),public.review_details(jsonb),public.publish_result(jsonb),public.create_group(jsonb),public.set_group_member(jsonb),public.write_post(jsonb),public.set_query_policy(jsonb),public.create_query(jsonb),public.reply_query(jsonb),public.transition_query(jsonb),public.revise_deadline(jsonb),public.write_article(jsonb),public.moderate_article(jsonb),public.directory(jsonb),public.student_progress(jsonb) to authenticated;
grant execute on function public.directory(jsonb) to anon;
grant all on all tables in schema public to service_role;
grant usage on schema private to service_role;
grant all on all tables in schema private to service_role;
grant usage, select on all sequences in schema public,private to service_role;
